describe('File Upload - Set Title and Description', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
    cy.get('[data-testid="file-upload-container"]').should('be.visible');
  });

  it('should successfully set title and description for an uploaded file', () => {
    const fileName = 'test-document.pdf';
    const fileTitle = 'Important Project Document';
    const fileDescription = 'This is a detailed description of the uploaded file for project management.';

    cy.get('input[type="file"]').selectFile('cypress/fixtures/sample.pdf', { force: true });

    cy.get('[data-testid="file-item"]').should('be.visible');
    cy.get('[data-testid="file-item"]').should('contain', fileName);

    cy.get('[data-testid="edit-file-btn"]').first().click();

    cy.get('[data-testid="file-title-input"]').should('be.visible');
    cy.get('[data-testid="file-title-input"]').clear().type(fileTitle);

    cy.get('[data-testid="file-description-input"]').should('be.visible');
    cy.get('[data-testid="file-description-input"]').clear().type(fileDescription);

    cy.get('[data-testid="save-file-metadata-btn"]').click();

    cy.get('[data-testid="success-message"]').should('contain', 'File metadata updated successfully');

    cy.get('[data-testid="file-title-display"]').should('contain', fileTitle);
    cy.get('[data-testid="file-description-display"]').should('contain', fileDescription);
  });

  it('should handle edge case with very long title and description', () => {
    const fileName = 'large-file.zip';
    const longTitle = 'A'.repeat(255);
    const longDescription = 'B'.repeat(1000);

    cy.get('input[type="file"]').selectFile('cypress/fixtures/archive.zip', { force: true });

    cy.get('[data-testid="file-item"]').should('be.visible');

    cy.get('[data-testid="edit-file-btn"]').first().click();

    cy.get('[data-testid="file-title-input"]').clear().type(longTitle);
    cy.get('[data-testid="file-description-input"]').clear().type(longDescription);

    cy.get('[data-testid="save-file-metadata-btn"]').click();

    cy.get('[data-testid="success-message"]').should('be.visible');

    cy.get('[data-testid="file-title-display"]').invoke('text').then((text) => {
      expect(text.length).to.be.lte(255);
    });

    cy.get('[data-testid="file-description-display"]').invoke('text').then((text) => {
      expect(text.length).to.be.lte(1000);
    });
  });

  it('should validate required fields and show error messages', () => {
    cy.get('input[type="file"]').selectFile('cypress/fixtures/sample.pdf', { force: true });

    cy.get('[data-testid="file-item"]').should('be.visible');

    cy.get('[data-testid="edit-file-btn"]').first().click();

    cy.get('[data-testid="file-title-input"]').clear();
    cy.get('[data-testid="file-description-input"]').clear();

    cy.get('[data-testid="save-file-metadata-btn"]').click();

    cy.get('[data-testid="error-message"]').should('contain', 'Title is required');
    cy.get('[data-testid="file-title-input"]').should('have.class', 'error');
  });

  it('should allow editing metadata multiple times for the same file', () => {
    const fileName = 'document.docx';
    const firstTitle = 'Initial Title';
    const secondTitle = 'Updated Title';
    const description = 'File description';

    cy.get('input[type="file"]').selectFile('cypress/fixtures/document.docx', { force: true });

    cy.get('[data-testid="file-item"]').should('be.visible');

    cy.get('[data-testid="edit-file-btn"]').first().click();
    cy.get('[data-testid="file-title-input"]').clear().type(firstTitle);
    cy.get('[data-testid="file-description-input"]').clear().type(description);
    cy.get('[data-testid="save-file-metadata-btn"]').click();

    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="file-title-display"]').should('contain', firstTitle);

    cy.get('[data-testid="edit-file-btn"]').first().click();
    cy.get('[data-testid="file-title-input"]').clear().type(secondTitle);
    cy.get('[data-testid="save-file-metadata-btn"]').click();

    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="file-title-display"]').should('contain', secondTitle);
    cy.get('[data-testid="file-description-display"]').should('contain', description);
  });

  it('should cancel editing without saving changes', () => {
    const originalTitle = 'Original Title';
    const newTitle = 'Unsaved Title';

    cy.get('input[type="file"]').selectFile('cypress/fixtures/sample.pdf', { force: true });

    cy.get('[data-testid="file-item"]').should('be.visible');

    cy.get('[data-testid="edit-file-btn"]').first().click();
    cy.get('[data-testid="file-title-input"]').clear().type(originalTitle);
    cy.get('[data-testid="save-file-metadata-btn"]').click();

    cy.get('[data-testid="file-title-display"]').should('contain', originalTitle);

    cy.get('[data-testid="edit-file-btn"]').first().click();
    cy.get('[data-testid="file-title-input"]').clear().type(newTitle);
    cy.get('[data-testid="cancel-edit-btn"]').click();

    cy.get('[data-testid="file-title-display"]').should('contain', originalTitle);
    cy.get('[data-testid="file-title-display"]').should('not.contain', newTitle);
  });
});
